import type { Register } from 'claude-code'

import { notificationArgv, parseUname, shouldNotify, toastText } from './format'
import type { Platform } from './format'

export const register: Register = (on, options) => {
  const minSeconds = typeof options.minSeconds === 'number' ? options.minSeconds : 30
  const sound = options.sound !== false
  const systemNotification = options.systemNotification === true
  const includeAnswerPreview = options.includeAnswerPreview === true

  // Probed once per load, and only when system notifications are on: the
  // mods API exposes no platform field, so ask the host's `uname -s`.
  let platform: Promise<Platform | undefined> | undefined

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (!shouldNotify(e, minSeconds)) return result

    const text = toastText(e, includeAnswerPreview)
    $.ui.toast(text)

    if (sound) {
      $.audio.play({ asset: 'sounds/done.wav' }).catch(() => undefined)
    }

    if (systemNotification) {
      platform ??= $.process
        .run(['uname', '-s'], { timeoutMs: 5000 })
        .then(ran => (ran.exitCode === 0 ? parseUname(ran.stdout) : undefined))
        .catch(() => undefined)
      platform
        .then(found =>
          found === undefined ? undefined : $.process.run(notificationArgv(found, 'Claude Code', text), { timeoutMs: 10000 }),
        )
        .catch(() => undefined)
    }

    return result
  })
}

