/**
 * Pure helpers for cm-done-toast: no `$`, so they are unit-tested directly.
 */

/** `2m 14s`, `45s`, `1h 3m`: the turn's wall-clock length, rounded to seconds. */
export function formatDuration(ms: number): string {
  const total = Math.max(0, Math.round(ms / 1000))
  const h = Math.floor(total / 3600)
  const m = Math.floor((total % 3600) / 60)
  const s = total % 60
  if (h > 0) return `${h}h ${m}m`
  if (m > 0) return `${m}m ${s}s`
  return `${s}s`
}

/** The fields of `turn.complete` this mod reads. */
export type TurnFacts = {
  durationMs: number
  isAborted: boolean
  agentId?: string
  reason: string
}

/**
 * Whether a finished turn deserves a toast: the main loop's (no `agentId`),
 * not interrupted, and at least `minSeconds` long.
 */
export function shouldNotify(turn: TurnFacts, minSeconds: number): boolean {
  if (turn.agentId !== undefined) return false
  if (turn.isAborted || turn.reason === 'aborted') return false
  return turn.durationMs >= Math.max(0, minSeconds) * 1000
}

/** The first `max` characters of the answer on one line, or '' when empty. */
export function preview(answer: string, max = 80): string {
  const line = answer.replace(/\s+/g, ' ').trim()
  if (line.length <= max) return line
  return `${line.slice(0, max - 1).trimEnd()}…`
}

/** The toast text: `Done in 2m 14s`, or with the answer's opening words. */
export function toastText(turn: TurnFacts & { answer: string }, withPreview: boolean): string {
  const head = turn.reason === 'error' ? `Stopped on an error after ${formatDuration(turn.durationMs)}` : `Done in ${formatDuration(turn.durationMs)}`
  const tail = withPreview ? preview(turn.answer) : ''
  return tail === '' ? head : `${head} · ${tail}`
}

/** `Darwin` / `Linux` from `uname -s`, or undefined for anything else. */
export type Platform = 'darwin' | 'linux'

export function parseUname(stdout: string): Platform | undefined {
  const name = stdout.trim().toLowerCase()
  if (name === 'darwin') return 'darwin'
  if (name === 'linux') return 'linux'
  return undefined
}

/** Escapes a string for an AppleScript double-quoted literal. */
function appleString(text: string): string {
  return `"${text.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`
}

/**
 * The argv that raises a desktop notification on this platform: osascript
 * on macOS, notify-send (libnotify) on Linux. No shell is involved.
 */
export function notificationArgv(platform: Platform, title: string, body: string): string[] {
  if (platform === 'darwin') {
    return ['osascript', '-e', `display notification ${appleString(body)} with title ${appleString(title)}`]
  }
  return ['notify-send', '--app-name=Claude Code', title, body]
}

